    #define     BA_KPINT_KPINT_ROW_KEY_PRESSED                 0x0008
    #define     B16KPINT_KPINT_ROW_KEY_PRESSED                 0x0008
    #define   LSb32KPINT_KPINT_ROW_KEY_PRESSED                    0
    #define   LSb16KPINT_KPINT_ROW_KEY_PRESSED                    0
