///                                                 * CPU PLL Bypass switch
///                                                 * 0:  Use PLL
///                                                 * 1:  Bypass PLL
///                                                 ###
///               %unsigned 1  aPLL_0SWBypass            0x0
///                                    : refClk                    0x1
///                                    : pllClk                    0x0
///                                                 ###
///                                                 * APLL0 PLL Bypass switch
///                                                 * 0:  Use PLL
///                                                 * 1:  Bypass PLL
///                                                 ###
///               %unsigned 1  aPLL_1SWBypass            0x0
///                                    : refClk                    0x1
///                                    : pllClk                    0x0
///                                                 ###
///                                                 * APLL1 Bypass switch
///                                                 * 0:  Use PLL
///                                                 * 1:  Bypass PLL
///                                                 ###
///               %unsigned 1  vPLL_0SWBypass            0x0
///                                    : refClk                    0x1
///                                    : pllClk                    0x0
///                                                 ###
///                                                 * VPLL0 Bypass switch
///                                                 * 0:  Use PLL
///                                                 * 1:  Bypass PLL
///                                                 ###
///               %unsigned 1  vPLL_1SWBypass            0x0
///                                    : refClk                    0x1
///                                    : pllClk                    0x0
///                                                 ###
///                                                 * VPLL1 Bypass switch
///                                                 * 0:  Use PLL
///                                                 * 1:  Bypass PLL
///                                                 ###
///               %%        24         # Stuffing bits...
///     @ 0x00404                      (W-)
///     #         # Stuffing bytes...
///               %% 224
///     @ 0x00420 clkEnable            (P-)
///               ###
///               * Clock enable register provides the option to switch  clocks
///               * OFF for power saving.
///               * All these clocks are using perifSysClk as clock source, except
///               * for gpuSysClk which is on dClk.
///               * To provide software backward compatible,
///               * Please never remove register bits even if the clock gators are
///               * removed.
///               * Leave a 'not used' comment if the bit field is not used in
///               * current project.
///               * Please always add new register bit at the end.
///               ###
///               %unsigned 1  usb0CoreClkEn             0x1
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * USB0 Core Clock enable register
///                                                 * 0 : disable
///                                                 * 1 : enable
///                                                 ###
///               %unsigned 1  sdioSysClkEn              0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * SDIO  AXI clock  enable register
///                                                 * 0 : disable
///                                                 * 1 : enable
///                                                 ###
///               %unsigned 1  emmcSysClkEn              0x1
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * EMMC AXI clock  enable register
///                                                 * 0 : disable
///                                                 * 1 : enable
///                                                 ###
///               %unsigned 1  gpuAxiClkEn               0x1
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * GPU axi  clock  enable register
///                                                 * 0 : disable
///                                                 * 1 : enable
///                                                 ###
///               %unsigned 1  gethRgmiiSysClkEn         0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * RGMII sys clk enable register
///                                                 * 0 : disable
///                                                 * 1 : enable
///                                                 ###
///               %unsigned 1  sdio1SysClkEn             0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * SDIO1 clock  enable register
///                                                 * 0 : disable
///                                                 * 1 : enable
///                                                 ###
///               %unsigned 1  usb1CoreClkEn             0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * USB1 Core Clock enable register
///                                                 * 0 : disable
///                                                 * 1 : enable
///                                                 ###
///               %unsigned 1  gethRgmii1SysClkEn        0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * RGMII1 sys clk enable register
///                                                 * 0 : disable
///                                                 * 1 : enable
///                                                 ###
///               %unsigned 1  usb0PhyRefClkEn           0x1
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * USB0 PHY REF CLK enable register
///                                                 * 0 : disable
///                                                 * 1 : enable
///                                                 ###
///               %unsigned 1  usb1PhyRefClkEn           0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * USB1 PHY REF CLK enable register
///                                                 * 0 : disable
///                                                 * 1 : enable
///                                                 ###
///               %unsigned 1  apbUART0ClkEn             0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * UART0 Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 ###
///               %unsigned 1  apbUART1ClkEn             0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * UART1 Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 ###
///               %unsigned 1  apbUART2ClkEn             0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * UART2 Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 ###
///               %unsigned 1  apbUART3ClkEn             0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * UART3 Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 ###
///               %unsigned 1  apbI2C0ClkEn              0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * I2C0 Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 ###
///               %unsigned 1  apbI2C1ClkEn              0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * I2C1 Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 ###
///               %unsigned 1  apbSPI0ClkEn              0x1
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * SPI0 Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 ###
///               %unsigned 1  apbSPI1ClkEn              0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * SPI1 Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 ###
///               %unsigned 1  apbSPI2ClkEn              0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
