///                                                 * SPI2 Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 ###
///               %unsigned 1  apbSPI3ClkEn              0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * SPI3 Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 ###
///               %unsigned 1  apbGPIOClkEn              0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * GPIO Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 ###
///               %unsigned 1  apbTimersClkEn            0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * Timers Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 ###
///               %unsigned 1  apbSysCntClkEn            0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * SysCnt Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 ###
///               %unsigned 1  apbWDTClkEn               0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * WDT Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 ###
///               %unsigned 1  apbDmaClkEn               0x0
///                                    : enable                    0x1
///                                    : disable                   0x0
///                                                 ###
///                                                 * DMA250 Clk enable register
///                                                 * 0:disable
///                                                 * 1:enable
///                                                 * Following are control registers for clock generation logics in
///                                                 * global.
///                                                 * They can select different pll source, set different diver and
///                                                 * turn on/off the clocks
///                                                 * fast reference clock for cpu and ddr
///                                                 * Provide fast backup clock from syspll to cpu and ddr when cpupll
///                                                 * or mempll is down for re-configuration
///                                                 ###
///               %%        7          # Stuffing bits...
///     @ 0x00424                      (W-)
///     #         # Stuffing bytes...
///               %% 224
///     @ 0x00440                      (P)
///     # 0x00440 cpufastRefClk        
///               $clkD2               cpufastRefClk     REG          
///                                    ###
///                                    * Fast backup clock for cpu when cpupll is bypass
///                                    ###
///     @ 0x00444                      (P)
///     # 0x00444 memfastRefClk        
///               $clkD2               memfastRefClk     REG          
///                                    ###
///                                    * Fast backup clock for mc5 when mempll is bypass
///                                    * System bus clock
///                                    ###
///     @ 0x00448                      (P)
///     # 0x00448 cfgClk               
///               $clkD8               cfgClk            REG          
///                                    ###
///                                    * System AHB Clock
///                                    ###
///     @ 0x0044C                      (P)
///     # 0x0044C sysClk               
///               $clkD4               sysClk            REG          
///                                    ###
